import hashlib
from typing import Callable, Dict, Any, List

class ToolRegistry:
    """A sandboxed registry for tools an agent can use."""

    def __init__(self):
        self._tools: Dict[str, Callable] = {}

    def register(self, func: Callable):
        """Decorator to register a tool."""
        if not callable(func):
            raise TypeError("Tool must be a callable function.")
        self._tools[func.__name__] = func
        return func

    def call(self, tool_name: str, *args, **kwargs) -> Any:
        """Execute a tool by name."""
        if tool_name not in self._tools:
            raise ValueError(f"Tool '{tool_name}' not found. Available tools: {list(self._tools.keys())}")

        # In a real sandbox, you'd add more restrictions here:
        # - Resource limits (CPU, memory)
        # - Filesystem access control
        # - Network call filtering
        # - For true determinism and security, tools would ideally be compiled
        #   WASM modules executed via `wasmtime`, ensuring isolated and
        #   reproducible execution environments. This Python callable approach
        #   is a placeholder for the MVP.
        return self._tools[tool_name](*args, **kwargs)

    def get_tool_names(self) -> List[str]:
        return list(self._tools.keys())

    def get_deterministic_hash(self) -> str:
        """
        Generates a deterministic hash of the tool registry's state.
        For now, this is based on the sorted names of registered tools.
        A more robust implementation would hash tool signatures or even
        the bytecode/WASM modules themselves.
        """
        tool_names = sorted(self.get_tool_names())
        hasher = hashlib.sha256()
        for name in tool_names:
            hasher.update(name.encode('utf-8'))
        return hasher.hexdigest()

